"import os


def write_file(path, content):
    """Helper that writes content to a file, creating intermediate dirs as needed."""
    dirname = os.path.dirname(path)
    if dirname:
        os.makedirs(dirname, exist_ok=True)
    with open(path, "w") as f:
        f.write(content)


